INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(126852, 'ruRU', '', 'Передай Модере мои приветствия, $c. И... спасибо.', 24330),
(126876, 'ruRU', '', 'Приятно было работать с тобой! Спасибо, что спас наш город.', 24330),
(126877, 'ruRU', '', 'Заглядывай в Браденсбрук время от времени, птиц настрелять ещё хватит!', 24330),
(126878, 'ruRU', '', 'Действуй быстро! Легион скоро захватит нас.', 24330),
(126879, 'ruRU', '', 'Защитник, я рад, что дозвонился до тебя. Как, без сомнения, уже сообщила Виктория, мы нашли мать бесов, Агату.', 24330),
(126880, 'ruRU', '', 'К этому моменту она, вероятно, уже подчинила себе большую часть силы, украденной у Левии. Если это так, невозможно сказать, на что она способна.', 24330),
(126881, 'ruRU', '', 'Её местоположение хорошо защищено, но наши маги Киринтора должны быть способны открыть к ней портал на короткое время.', 24330),
(126882, 'ruRU', '', 'Мать бесов нужно остановить! Удачи, защитник.', 24330),
(126884, 'ruRU', '', 'Ты слишком поздно! Сила Левии принадлежит мне! Используя её знания, мои прислужники проникнут в Киринтор и уничтожат его изнутри!', 24330),
(126885, 'ruRU', '', 'Даже сейчас мои саяады соблазняют твоих слабовольных магов. Твои союзники добровольно сдадутся Легиону!', 24330),
(126886, 'ruRU', '', 'Но сначала тебя нужно наказать за то, что ты забрал моего маленького питомца.', 24330),
(126888, 'ruRU', '', 'Нет... Мои красавчики!', 24330),
(126889, 'ruRU', '', 'Ты... заплатишь за это! Ты... заплатишь...', 24330),
(126933, 'ruRU', '', 'Тренируйся или погибни. Здесь нет вторых шансов.', 24330),
(126934, 'ruRU', '', 'Ты действительно считаешь, что твои спутники готовы присоединиться к нашему штурму?', 24330),
(126978, 'ruRU', '', 'Будь они прокляты! Идём!', 24330),
(127003, 'ruRU', '', 'Духи в этих руинах связаны с Пылающим Легионом древним договором. Упокой их, чтобы они обрели мир.', 24330),
(127004, 'ruRU', '', 'Отлично сработано, защитник. Пусть их духи наконец обретут покой.', 24330),
(127005, 'ruRU', '', 'Верховный лорд, оружие, что ты держишь, необходимо, чтобы освободить этих духов, связанных скверной. Уничтожь их кулоны и освободи моих предков от древнего проклятия.', 24330),
(127006, 'ruRU', '', 'Благодарю тебя, Верховный лорд. Ты принёс покой моим предкам.', 24330),
(127009, 'ruRU', '', 'Ты права, С\'тено. Либо мы рискнём, либо всё равно умрём. Убийцса $n, нам нужно добраться до главной консоли наверху!', 24330),
(127010, 'ruRU', '', 'Внимание - эффектная сцена: Кузня Скверны уничтожает один из кораблей Легиона, а остальные уходят в прыжок!', 24330),
(127011, 'ruRU', '', 'Им не следовало подходить так ссблизко, Злоба. Почему Кузня Скверны не открыла по ним огонь?', 24330),
(127012, 'ruRU', '', 'Не время для гадких намёков, С\'тено, дорогая. Они первым делом вывели из строя наше оружие. Если поможешь убить этих мерзких тварей, мы сможем подумать о ремонте!', 24330),
(127013, 'ruRU', '', 'Хватит препираться! Нам нужно спасать корабль!', 24330),
(127016, 'ruRU', '', 'Что ж, это было некстати. Конечно, кто-то с твоими навыками способен его воскресить?', 24330),
(127019, 'ruRU', '', 'Прости, мы не можем собрать ещё один отряд, пока ты не развернёшь уже собранные войска.', 24330),
(127021, 'ruRU', '', 'Инферналы - непростые штуки, и крайне мощные. Нам нужно быть с ними осторожными. У тебя всё ещё есть Филактерия, было бы безрассудно держать больше одной.', 24330),
(127023, 'ruRU', '', 'Могущество Даларана можно направить лишь однажды. Похоже, у тебя всё ещё есть Фокусирующий кристалл. Как только ты его высвободишь, мои маги смогут создать для тебя новый.', 24330),
(127027, 'ruRU', '', 'Мы просто не готовы иметь несколько Разломных сердечников одновременно. У тебя всё ещё есть один. Как только ты его высвободишь, мы начнём заряжать следующий.', 24330),
(127057, 'ruRU', '', 'Будьте защищены, герои!', 24330),
(127058, 'ruRU', '', 'Обязательно тебе быть всегда так близко, Роланд?', 24330),
(127059, 'ruRU', '', 'Конечно, у тебя есть другие дела, Роланд?', 24330),
(127060, 'ruRU', '', 'Это место не напоминает тебе дом?', 24330),
(127063, 'ruRU', '', 'Идём, Роланд. Покинем это отвратительное место, пока ты снова не заболел.', 24330),
(127065, 'ruRU', '', 'Клинок Тени! Сюда!', 24330),
(127066, 'ruRU', '', 'Я считаю себя искусным охотником на нежить, и даже я не заметил этого сразу.', 24330),
(127067, 'ruRU', '', 'Но смотри, что происходит, если разрезать вот здесь...', 24330),
(127068, 'ruRU', '', 'Оно не должно так делать, и уж точно не должно быть такого цвета.', 24330),
(127069, 'ruRU', '', 'Он говорил вполне связно, а его кожа... так хорошо сохранилась. Но пара характерных признаков его выдали.', 24330);
